const requester = $input.first().json;
const { contacts } = $('Validate Session ken & Rows').first().json;

if (!requester.id || !requester.active) {
  throw new Error('Invalid session.');
}

const queryParams = [];
let paramIndex = 1;

// companies.name is UNIQUE — upsert distinct company names first, then
// link each contact to its company via account_id (contacts has no
// company_name column; company is a separate normalized table).
const companyNames = [...new Set(
  contacts.map((c) => (c.company_name || '').trim()).filter((n) => n)
)];

const companyValuesSql = companyNames.map((name) => {
  const sql = `($${paramIndex}::varchar, $${paramIndex + 1}::integer, NOW(), NOW())`;
  queryParams.push(name, requester.id);
  paramIndex += 2;
  return sql;
});

const contactValuesSql = contacts.map((c) => {
  const companyName = (c.company_name || '').trim() || null;
  const sql = `($${paramIndex}::varchar, $${paramIndex+1}::varchar, $${paramIndex+2}::varchar, $${paramIndex+3}::varchar, $${paramIndex+4}::varchar, $${paramIndex+5}::varchar, $${paramIndex+6}::varchar, $${paramIndex+7}::varchar, $${paramIndex+8}::integer)`;
  queryParams.push(
    c.first_name, c.last_name, c.email, c.phone,
    c.city, c.country, c.lead_status, companyName, requester.id
  );
  paramIndex += 9;
  return sql;
});

const contactsCte = `new_contacts (first_name, last_name, email, phone, city, country, lead_status, company_name, owner_id) AS (
  VALUES ${contactValuesSql.join(', ')}
)`;

const sqlQuery = companyNames.length
  ? `
    WITH upserted_companies AS (
      INSERT INTO companies (name, owner_id, created_at, updated_at)
      VALUES ${companyValuesSql.join(', ')}
      ON CONFLICT (name) DO UPDATE SET name = EXCLUDED.name
      RETURNING id, name
    ),
    ${contactsCte}
    INSERT INTO contacts (first_name, last_name, email, phone, city, country, lead_status, account_id, owner_id, lead_source, created_by, created_at, updated_at)
    SELECT nc.first_name, nc.last_name, nc.email, nc.phone, nc.city, nc.country, nc.lead_status, uc.id, nc.owner_id, 'CSV Import', nc.owner_id, NOW(), NOW()
    FROM new_contacts nc
    LEFT JOIN upserted_companies uc ON uc.name = nc.company_name
    WHERE (COALESCE(nc.email, '') = '' OR NOT EXISTS (SELECT 1 FROM contacts x WHERE lower(x.email) = lower(nc.email) AND x.is_archived = false))
    RETURNING id;
  `
  : `
    WITH ${contactsCte}
    INSERT INTO contacts (first_name, last_name, email, phone, city, country, lead_status, account_id, owner_id, lead_source, created_by, created_at, updated_at)
    SELECT nc.first_name, nc.last_name, nc.email, nc.phone, nc.city, nc.country, nc.lead_status, NULL::integer, nc.owner_id, 'CSV Import', nc.owner_id, NOW(), NOW()
    FROM new_contacts nc
    WHERE (COALESCE(nc.email, '') = '' OR NOT EXISTS (SELECT 1 FROM contacts x WHERE lower(x.email) = lower(nc.email) AND x.is_archived = false))
    RETURNING id;
  `;

return [{ json: { sqlQuery, queryParams } }];

const insertedRows = $input.all().map((item) => item.json).filter((r) => r && r.id !== undefined);
const v = $('Validate Session ken & Rows').first().json;
const alreadyExisted = v.contacts.length - insertedRows.length;
return [{
  json: {
    success: true,
    received: v.received,
    inserted_count: insertedRows.length,
    inserted_ids: insertedRows.map((r) => r.id),
    // rows left out, with the reason, so the user can fix and re-import them
    skipped: v.skipped,
    skipped_count: v.skipped.length,
    // valid rows whose email already belongs to a contact in the CRM
    already_existed_count: alreadyExisted,
  }
}];

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
if (!token) throw new Error('Invalid or missing session token.');
return [{ json: { token, contacts: body.contacts || [] } }];

const r = $input.first().json;
if (!r.valid) throw new Error('Invalid session.');

const raw = $('Extract Bearer Token ken & Rows').first().json.contacts;
const MAX_ROWS = 500;
if (!Array.isArray(raw)) throw new Error('"contacts" must be an array of contact rows.');
if (raw.length === 0) throw new Error('No contacts to import.');
if (raw.length > MAX_ROWS) throw new Error(`Import at most ${MAX_ROWS} contacts at a time (split larger files).`);

// Wrong-typed values (objects/arrays/booleans) become '' instead of "[object Object]"; control characters are stripped.
const clean = (v) => (typeof v === 'string' || typeof v === 'number' ? String(v) : '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
const EMAIL_RE = /^[^\s@<>"'`,;()\[\]\\]+@[^\s@<>"'`,;()\[\]\\]+\.[^\s@<>"'`,;()\[\]\\]{2,}$/;
const LIMITS = { first_name: 150, last_name: 150, email: 255, phone: 50, city: 100, country: 100, company_name: 255 };
const STATUSES = ['New', 'Active', 'Customer', 'Inactive', 'Unqualified', 'Do Not Contact'];

const rows = [];
const skipped = [];
const seen = new Set();
raw.forEach((c, i) => {
  const row = i + 1;
  const skip = (reason) => skipped.push({ row, reason });
  if (!c || typeof c !== 'object' || Array.isArray(c)) return skip('Row is not a contact object.');
  const r2 = {
    first_name: clean(c.first_name), last_name: clean(c.last_name), email: clean(c.email).toLowerCase(), phone: clean(c.phone),
    city: clean(c.city), country: clean(c.country), lead_status: clean(c.lead_status) || 'New', company_name: clean(c.company_name),
  };
  if (!r2.first_name) return skip('first_name is required.');
  if (r2.email && !EMAIL_RE.test(r2.email)) return skip('email is not valid.');
  for (const [k, max] of Object.entries(LIMITS)) { if ((r2[k] || '').length > max) return skip(`${k} is too long (maximum ${max} characters).`); }
  if (!STATUSES.includes(r2.lead_status)) return skip(`lead_status must be one of ${STATUSES.join(', ')}.`);
  if (r2.email) {
    if (seen.has(r2.email)) return skip('Duplicate email within this file.');
    seen.add(r2.email);
  }
  rows.push(r2);
});
if (rows.length === 0) throw new Error(`None of the ${raw.length} rows could be imported. First problem is row ${skipped[0].row}, ${skipped[0].reason}`);

return [{ json: { id: r.userId, role: r.role, name: r.user?.name, active: r.active, contacts: rows, skipped, received: raw.length } }];
